import subprocess, random
from concurrent.futures import ThreadPoolExecutor
BIN="/workspace/dataset/test19_executable"
random.seed(11)
NDS=[ "".join(chr(b+i) for i in range(10)) for b in (0x30,0x660,0x966,0xFF10,0x9E6,0xE50,0x6F0,0xBE6,0x104A0)]
WS=['',' ','\t','\n','\r','\x0b','\x0c','\xa0',' ','　',' ',' ',' ']
def gen():
    n=random.randint(1,3)
    digs=[]
    for _ in range(n):
        script=random.choice(NDS)
        digs.append(script[random.randint(0,9)])
    core="".join(digs)
    if random.random()<0.3:
        # insert single underscores between digits
        core="_".join(core)
    if random.random()<0.3: core="+"+core
    s=random.choice(WS)+core+random.choice(WS)
    return s
def expected(s):
    return int(s)
def run(s):
    a=[BIN,"--a","1","--b","2","--c","3","--d","hi","--e","9","--f",s,"--g","5","--h","yo","--i","6"]
    r=subprocess.run(a,capture_output=True)
    return r.returncode, r.stdout.split(b"\n")
cases=[]
while len(cases)<250:
    s=gen()
    try: v=int(s)
    except ValueError: continue
    if 0<=v<=255: cases.append((s,v))
def check(t):
    s,v=t
    rc,lines=run(s)
    if rc!=0: return (s,v,"rc=%d"%rc)
    got=lines[4]  # result5 line, as raw bytes of the repr
    want=repr(bytes([v])).encode()
    return None if got==want else (s,v,"got=%r want=%r"%(got,want))
with ThreadPoolExecutor(max_workers=32) as ex:
    bad=[x for x in ex.map(check,cases) if x]
print("value cases:",len(cases),"MISMATCHES:",len(bad))
for b in bad[:20]: print("   ",b)
